<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Printer, ReceiptText, Search, ArrowRight } from '@lucide/vue'
import { api, list, money, dateLabel } from '../api'
import type { Order } from '../types'
import AppModal from '../components/AppModal.vue'
const orders=ref<Order[]>([]), filter=ref('all'), query=ref(''), error=ref(''), selected=ref<Order>(), method=ref('cash'), busy=ref(false), loading=ref(true)
const visible=computed(()=>orders.value.filter(o=>(filter.value==='all'||o.status===filter.value)&&(`${o.id} ${o.table} ${o.waiter}`.toLowerCase().includes(query.value.toLowerCase()))))
async function load(){try{orders.value=await list<Order>('orders/')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
onMounted(load)
async function pay(){if(!selected.value)return;busy.value=true;error.value='';try{selected.value=await api<Order>(`orders/${selected.value.id}/pay/`,{method:'POST',body:JSON.stringify({payment_method:method.value})});await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function print(){window.print()}
</script>
<template><div class="page-heading"><div><span class="eyebrow">SAVDO TARIXI</span><h1>Buyurtmalar<span class="heading-dot">.</span></h1><p>Ochiq hisoblar, to‘lovlar va chek tafsilotlari.</p></div><RouterLink to="/pos" class="button primary">Kassaga o‘tish <ArrowRight :size="17"/></RouterLink></div><p v-if="error" class="alert error">{{ error }}</p><section class="panel"><div class="table-toolbar"><div class="tabs"><button :class="{selected:filter==='all'}" @click="filter='all'">Barchasi</button><button :class="{selected:filter==='open'}" @click="filter='open'">Ochiq hisoblar</button><button :class="{selected:filter==='paid'}" @click="filter='paid'">To‘langan</button></div><div class="search-field"><Search :size="17"/><input v-model="query" aria-label="Buyurtma qidirish" placeholder="Raqam, stol yoki ofitsiant…"></div></div><div class="table-wrap"><table><thead><tr><th>HISOB</th><th>STOL / OFITSIANT</th><th>VAQT</th><th>SUMMA</th><th>HOLAT</th><th/></tr></thead><tbody><tr v-for="order in visible" :key="order.id"><td><strong>#{{ String(order.id).padStart(4,'0') }}</strong><small>{{ order.lines.length }} xil taom</small></td><td>{{ order.table ? `${order.table}-stol` : 'Tezkor savdo' }}<small>{{ order.waiter || '—' }}</small></td><td>{{ dateLabel(order.created_at) }}</td><td class="number">{{ money(order.total) }} so‘m</td><td><span class="status" :class="order.status">{{ order.status==='paid'?'To‘langan':'Ochiq hisob' }}</span></td><td><button class="text-link" @click="selected=order; error=''">Ochish <ArrowRight :size="15"/></button></td></tr></tbody></table><div v-if="!visible.length" class="empty-state"><ReceiptText :size="38" :stroke-width="1.3"/><h3>{{ loading?'Yuklanmoqda…':'Hali buyurtmalar yo‘q' }}</h3><p>Kassada yaratilgan hisoblar shu yerda saqlanadi.</p></div></div></section><AppModal :open="!!selected" :title="`Hisob #${selected?.id || ''}`" @close="!busy && (selected=undefined)"><template v-if="selected"><div class="receipt"><h2>HONIM</h2><p>{{ selected.status==='paid'?'TO‘LOV QAYDI':'OLDINDAN HISOB' }}</p><small>{{ dateLabel(selected.created_at) }} · #{{ selected.id }}</small><p v-if="selected.table">Stol: {{ selected.table }} · {{ selected.waiter }}</p><div class="receipt-lines"><div v-for="line in selected.lines" :key="line.id"><span>{{ line.name }}<small>{{ line.quantity }} × {{ money(line.price) }} {{ line.note ? `· ${line.note}` : '' }}</small></span><strong>{{ money(Number(line.price)*line.quantity) }}</strong></div></div><div class="cart-total"><span>JAMI</span><strong>{{ money(selected.total) }}</strong></div><p>{{ selected.payment_method==='cash'?'Naqd':selected.payment_method==='card'?'Karta':'To‘lov olinmagan' }}</p><small>Mahalliy sinov cheki · fiskal chek emas</small></div><p v-if="error" class="alert error">{{ error }}</p><form v-if="selected.status==='open'" @submit.prevent="pay"><label>To‘lov usuli<select v-model="method"><option value="cash">Naqd</option><option value="card">Terminalda tasdiqlangan karta</option></select></label><button class="button primary full" :disabled="busy">{{ busy?'Saqlanmoqda…':'To‘lovni qayd etish' }}</button></form><button class="button secondary full" @click="print"><Printer :size="17"/>Brauzer orqali chiqarish</button></template></AppModal></template>
